            || body.checkOut() == null
            || body.guests() == null
            || body.ratePlan() == null) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
    }

    Guest guest = buildGuest(body);
    return new NewReservation(
            body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
}

private static Guest buildGuest(CreateReservationRequest body) {
    boolean hasCpf = !isBlank(body.guestCpf());
    boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
    boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());

    int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);

    if (identificationCount != 1) {
        throw new HotelException(ErrorCode.INVALID_REQUEST,
                "exactly one guest identification must be provided: guestCpf, or companyCnpj + companyName, "
                + "or guestPassport + guestCountry");
    }

    if (hasCpf) {
        return new IndividualGuest(body.guestName(), body.guestEmail(), body.guestCpf());
    }
    if (hasCompany) {
        return new CorporateGuest(body.guestName(), body.guestEmail(), body.companyCnpj(), body.companyName());
    }
    return new ForeignGuest(body.guestName(), body.guestEmail(), body.guestPassport(), body.guestCountry());
}

